import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.CoPVQkzc.js";const u=JSON.parse('{"title":"Upgrade Guide","description":"How to upgrade to a newer version","frontmatter":{"title":"Upgrade Guide","description":"How to upgrade to a newer version"},"headers":[],"relativePath":"engine/upgrade_guide.md","filePath":"engine/upgrade_guide.md","lastUpdated":1788476353000}'),o={name:"engine/upgrade_guide.md"};function s(n,e,l,d,c,p){return r(),t("div",null,e[0]||(e[0]=[i('<h1 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h1><p>This guide covers how to upgrade your OIE installation to a newer version.</p><h2 id="before-you-upgrade" tabindex="-1">Before you upgrade <a class="header-anchor" href="#before-you-upgrade" aria-label="Permalink to &quot;Before you upgrade&quot;">​</a></h2><h3 id="_1-back-up-everything" tabindex="-1">1. Back up everything <a class="header-anchor" href="#_1-back-up-everything" aria-label="Permalink to &quot;1. Back up everything&quot;">​</a></h3><p>Before upgrading, create backups of:</p><ul><li><p><strong>Server configuration</strong>: Export via the Administrator (<strong>Settings &gt; Server Tab &gt; Server Tasks &gt; Backup Config</strong>) or via the CLI (<code>exportcfg &quot;path&quot;</code>). The server configuration includes channels, code templates, alerts, global scripts, and server properties.</p><blockquote><p><strong>Warning:</strong> The Server Configuration file does <strong>not</strong> include user accounts, events, or message/attachment data. Back those up separately if needed.</p></blockquote></li><li><p><strong>Database</strong>: If using the embedded Derby database, back up the <code>appdata/mirthdb</code> folder. If using an external database (PostgreSQL, MySQL, Oracle, SQL Server), create a backup using your database administration tool.</p></li><li><p><strong>Application data directory</strong> (<code>appdata/</code>): Contains keystore, embedded database, and configuration map</p></li><li><p><strong>Configuration files</strong> (<code>conf/</code>): Especially <code>mirth.properties</code> and any customized files</p></li><li><p><strong>Custom database driver entries</strong>: If you have added entries to <code>conf/dbdrivers.xml</code>, back up that file</p></li><li><p><strong>JVM parameters</strong>: If you have modified heap size or other JVM settings, back up all <code>*.vmoptions</code> files in the installation directory</p></li><li><p><strong>CLI configuration</strong>: If you have customized <code>conf/mirth-cli-config.properties</code>, back up that file</p></li><li><p><strong>Custom libraries</strong> (<code>custom-lib/</code>): Any user-provided JARs</p></li></ul><h3 id="_2-review-release-notes" tabindex="-1">2. Review release notes <a class="header-anchor" href="#_2-review-release-notes" aria-label="Permalink to &quot;2. Review release notes&quot;">​</a></h3><p>Check the <a href="https://github.com/OpenIntegrationEngine/engine/releases" target="_blank" rel="noreferrer">Releases page</a> for:</p><ul><li>Breaking changes</li><li>New features</li><li>Deprecated features</li><li>Database migration notes</li><li>Java version requirements</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If you are upgrading through multiple versions (e.g., from 3.x to 4.x), review the release notes for <strong>all</strong> intermediate versions you are skipping. Each version may introduce changes that affect your installation.</p></div><h3 id="_3-plan-downtime" tabindex="-1">3. Plan downtime <a class="header-anchor" href="#_3-plan-downtime" aria-label="Permalink to &quot;3. Plan downtime&quot;">​</a></h3><p>Upgrading requires stopping the server. Plan a maintenance window during low-traffic periods.</p><h3 id="_4-test-in-a-non-production-environment" tabindex="-1">4. Test in a non-production environment <a class="header-anchor" href="#_4-test-in-a-non-production-environment" aria-label="Permalink to &quot;4. Test in a non-production environment&quot;">​</a></h3><p>If possible, test the upgrade in a staging environment first:</p><ol><li>Restore your production backup to a test instance</li><li>Perform the upgrade</li><li>Verify channels start and process correctly</li><li>Test critical workflows end-to-end</li></ol><h2 id="upgrade-process" tabindex="-1">Upgrade process <a class="header-anchor" href="#upgrade-process" aria-label="Permalink to &quot;Upgrade process&quot;">​</a></h2><h3 id="using-the-installer" tabindex="-1">Using the installer <a class="header-anchor" href="#using-the-installer" aria-label="Permalink to &quot;Using the installer&quot;">​</a></h3><p>The platform installer supports in-place upgrades:</p><ol><li>Exit and stop the <strong>Administrator</strong> and <strong>server service/daemon</strong> before proceeding</li><li>Run the new version installer, choosing the update option</li><li>Point it to the existing installation directory</li><li>The installer preserves your <code>appdata/</code>, <code>conf/</code>, <code>custom-lib/</code>, and other user data</li><li>Restore any custom changes you made to <code>*.vmoptions</code> files and <code>conf/mirth-cli-config.properties</code> (the installer may overwrite these with new defaults)</li><li>Start the server</li><li>The server automatically runs any required database schema migrations on startup</li></ol><h3 id="using-pre-packaged-distributions" tabindex="-1">Using pre-packaged distributions <a class="header-anchor" href="#using-pre-packaged-distributions" aria-label="Permalink to &quot;Using pre-packaged distributions&quot;">​</a></h3><p>For archive-based installations (ZIP/TAR.GZ):</p><ol><li>Exit and stop the <strong>Administrator</strong> and <strong>server service/daemon</strong></li><li>Back up the entire installation directory</li><li>Extract the new version to a temporary location</li><li>Copy your existing <code>conf/mirth.properties</code> to the new installation</li><li>Copy your <code>appdata/</code> directory to the new installation</li><li>Copy any <code>custom-lib/</code> files</li><li>Copy any custom extensions from <code>extensions/</code></li><li>Restore custom changes to <code>conf/dbdrivers.xml</code>, <code>*.vmoptions</code>, and <code>conf/mirth-cli-config.properties</code> as needed</li><li>Start the server from the new installation directory</li></ol><h3 id="using-docker" tabindex="-1">Using Docker <a class="header-anchor" href="#using-docker" aria-label="Permalink to &quot;Using Docker&quot;">​</a></h3><p>Update the image tag in your Docker configuration:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openintegrationengine/engine:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Ensure your data volumes are preserved across container updates.</p><h2 id="after-the-upgrade" tabindex="-1">After the upgrade <a class="header-anchor" href="#after-the-upgrade" aria-label="Permalink to &quot;After the upgrade&quot;">​</a></h2><h3 id="_1-verify-server-startup" tabindex="-1">1. Verify server startup <a class="header-anchor" href="#_1-verify-server-startup" aria-label="Permalink to &quot;1. Verify server startup&quot;">​</a></h3><p>Check the server logs (<code>logs/mirth.log</code>) for:</p><ul><li>Successful startup messages</li><li>Database migration completion</li><li>Extension loading</li><li>Any errors or warnings</li></ul><h3 id="_2-check-database-tasks" tabindex="-1">2. Check Database Tasks <a class="header-anchor" href="#_2-check-database-tasks" aria-label="Permalink to &quot;2. Check Database Tasks&quot;">​</a></h3><p>Navigate to <strong>Settings &gt; Database Tasks</strong> in the Administrator. Some upgrades create cleanup or optimization tasks for the underlying database. If no tasks appear, the database is up to date.</p><ul><li>These tasks are <strong>not</strong> run automatically. You must select a task row and click <strong>Run Task</strong> in the task panel on the left</li><li>Some tasks require affected channels to be <strong>stopped</strong> before they can execute</li><li>Tasks may take a long time on large databases; monitor progress via the Status column and server logs</li></ul><h3 id="_3-verify-channels" tabindex="-1">3. Verify channels <a class="header-anchor" href="#_3-verify-channels" aria-label="Permalink to &quot;3. Verify channels&quot;">​</a></h3><ol><li>Check that all channels are in their expected state (deployed/undeployed)</li><li>Start channels and verify message processing</li><li>Check the Message Browser for any errors</li><li>Test critical interfaces end-to-end</li></ol><h3 id="_4-verify-extensions" tabindex="-1">4. Verify extensions <a class="header-anchor" href="#_4-verify-extensions" aria-label="Permalink to &quot;4. Verify extensions&quot;">​</a></h3><p>Check <strong>Extensions</strong> in the Administrator to ensure all plugins and connectors loaded correctly. Custom extensions may not work after an upgrade; check the server log for errors and install updated versions if needed.</p><h2 id="rollback-plan" tabindex="-1">Rollback plan <a class="header-anchor" href="#rollback-plan" aria-label="Permalink to &quot;Rollback plan&quot;">​</a></h2><p>If the upgrade fails:</p><ol><li>Stop the server</li><li>Restore from your backup: <ul><li>Replace the installation directory with the backup</li><li>Restore the database from backup (if using an external database) or restore the <code>appdata/mirthdb</code> folder (if using embedded Derby)</li><li>Restore <code>conf/mirth.properties</code> and any other customized configuration files</li></ul></li><li>Start the old version</li></ol><p>You can also restore a server configuration backup via the Administrator (<strong>Settings &gt; Server Tab &gt; Server Tasks &gt; Restore Config</strong>). Note that this overwrites all current channels, alerts, code templates, server properties, global scripts, and plugin properties. A confirmation dialog gives you the option to automatically deploy all channels after the restore.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If database migrations have already run, you must restore the database to its pre-upgrade state. You cannot simply run the old version against a migrated database.</p></div><h2 id="common-upgrade-issues" tabindex="-1">Common upgrade issues <a class="header-anchor" href="#common-upgrade-issues" aria-label="Permalink to &quot;Common upgrade issues&quot;">​</a></h2><h3 id="java-version-mismatch" tabindex="-1">Java version mismatch <a class="header-anchor" href="#java-version-mismatch" aria-label="Permalink to &quot;Java version mismatch&quot;">​</a></h3><p>Newer OIE versions may require a newer Java version. Check the release notes for the minimum Java requirement and update Java before upgrading.</p><h3 id="extension-compatibility" tabindex="-1">Extension compatibility <a class="header-anchor" href="#extension-compatibility" aria-label="Permalink to &quot;Extension compatibility&quot;">​</a></h3><p>Custom or third-party extensions may not be compatible with the new version. Check with extension providers for updated versions.</p><h3 id="configuration-changes" tabindex="-1">Configuration changes <a class="header-anchor" href="#configuration-changes" aria-label="Permalink to &quot;Configuration changes&quot;">​</a></h3><p>New versions may introduce new configuration properties or change defaults. Compare the new <code>mirth.properties</code> template with your existing file and merge any new properties. Also check for changes to <code>dbdrivers.xml</code>, <code>log4j2.properties</code>, and <code>*.vmoptions</code> files.</p><h3 id="large-database-migrations" tabindex="-1">Large database migrations <a class="header-anchor" href="#large-database-migrations" aria-label="Permalink to &quot;Large database migrations&quot;">​</a></h3><p>Some version upgrades include significant database schema changes. These migrations can take a long time on large databases. Plan accordingly and monitor the <code>logs/mirth.log</code> for progress.</p><h2 id="version-specific-notes" tabindex="-1">Version-specific notes <a class="header-anchor" href="#version-specific-notes" aria-label="Permalink to &quot;Version-specific notes&quot;">​</a></h2><p>Check the <a href="https://github.com/OpenIntegrationEngine/engine/releases" target="_blank" rel="noreferrer">GitHub Releases</a> page for version-specific upgrade instructions, known issues, and migration notes.</p><h3 id="upgrading-to-4-6-0" tabindex="-1">Upgrading to 4.6.0 <a class="header-anchor" href="#upgrading-to-4-6-0" aria-label="Permalink to &quot;Upgrading to 4.6.0&quot;">​</a></h3><p>Four changes in 4.6.0 can break a working installation or change behavior silently. Read these before upgrading.</p><p><strong>Java 17 is the minimum.</strong> Older JVMs are no longer supported. Later Java LTS releases should work but are not officially tested, so a server pinned to Java 11 needs its runtime updated first.</p><p><strong>Xerces and xml-apis have been removed.</strong> Custom code that imports <code>org.apache.xerces.*</code> directly will fail to load. Migrate those imports to <code>javax.xml.parsers.*</code> and <code>org.xml.sax.*</code>. This affects code templates, channel scripts, and custom extensions alike, so search your scripts for the old package before you upgrade rather than after.</p><p><strong>Logins are case-insensitive by default.</strong> <code>admin</code>, <code>Admin</code>, and <code>ADMIN</code> now resolve to the same account. Existing accounts that relied on case-sensitive usernames continue to work through a compatibility path, but two accounts differing only in case are worth resolving before the upgrade rather than discovering afterward.</p><p><strong>HTTP parameter map ordering is now preserved.</strong> Previously the order was non-deterministic. Any script that happened to depend on the old ordering, deliberately or not, may behave differently.</p><p>Two operational notes:</p><ul><li>Installers remove the prior release as part of the upgrade, preserving the directories that must survive it, including <code>appdata</code>, <code>conf</code>, <code>extensions</code>, and <code>logs</code>.</li><li>The release remediates 24 known CVEs (1 critical, 10 high, 12 medium, 1 low) through dependency upgrades, among them log4j, the PostgreSQL JDBC driver, jSch, commons-lang3, and commons-text. That makes it a security upgrade as much as a feature one.</li></ul><p>The full release notes, including the complete dependency and CVE list, are published with the <a href="https://github.com/OpenIntegrationEngine/engine/releases/tag/v4.6.0" target="_blank" rel="noreferrer">v4.6.0 release</a>.</p>',62)]))}const g=a(o,[["render",s]]);export{u as __pageData,g as default};
